import Foundation

/// One public-domain poem from the bundled PoetryDB curation
/// (native/Sources/CaesuraCore/Resources/poems/poems.en.json, generated by
/// native/scripts/curate-poems.py). All fields mirror that JSON exactly.
public struct Poem: Codable, Equatable {
    public var id: String
    public var title: String
    public var author: String
    public var lines: [String]
    public var excerpt: [String]
    public var seasons: [String]
    public var months: [Int]
    public var authorBorn: String?
    public var authorDied: String?
    public var source: String

    public init(id: String, title: String, author: String, lines: [String],
                excerpt: [String], seasons: [String], months: [Int],
                authorBorn: String?, authorDied: String?, source: String) {
        self.id = id
        self.title = title
        self.author = author
        self.lines = lines
        self.excerpt = excerpt
        self.seasons = seasons
        self.months = months
        self.authorBorn = authorBorn
        self.authorDied = authorDied
        self.source = source
    }
}

public struct PoemCatalog: Codable {
    public var version: Int
    public var language: String
    public var attribution: String
    public var poems: [Poem]

    public init(version: Int, language: String, attribution: String, poems: [Poem]) {
        self.version = version
        self.language = language
        self.attribution = attribution
        self.poems = poems
    }

    /// CC BY 4.0 compliance: keep this line visible in the About tab and README.
    public static let attribution = "Poetry data from PoetryDB (https://poetrydb.org), licensed under CC BY 4.0."
}

/// Source of the poem catalog. A `RemotePoemProvider` (online refresh + disk
/// cache + fallback to bundled) can be added later without changing callers;
/// this release intentionally performs no network requests.
public protocol PoemProvider {
    func catalog() throws -> PoemCatalog
}

/// Serves the poem dataset bundled with CaesuraCore, looked up the same way
/// as the locale files (SPM strips the "Resources/" segment in built bundles;
/// older layouts keep it).
public struct BundledPoemProvider: PoemProvider {
    let bundle: Bundle

    public init(bundle: Bundle? = nil) {
        self.bundle = bundle ?? .module
    }

    public func catalog() throws -> PoemCatalog {
        for subdirectory in ["poems", "Resources/poems"] {
            let urls = bundle.urls(forResourcesWithExtension: "json", subdirectory: subdirectory) ?? []
            guard let url = urls.first(where: { $0.lastPathComponent == "poems.en.json" }) else { continue }
            let data = try Data(contentsOf: url)
            let catalog = try JSONDecoder().decode(PoemCatalog.self, from: data)
            if catalog.attribution != PoemCatalog.attribution {
                Log.warn("Caesura: bundled poem attribution changed, update the About tab and README")
            }
            return catalog
        }
        throw NSError(domain: "CaesuraCore.Poems", code: 1,
                      userInfo: [NSLocalizedDescriptionKey: "poems.en.json not found in the bundle"])
    }
}
